package hotel.reservations;

public enum RatePlan {
    /** Full price; the guest gets everything back when cancelling a confirmed reservation. */
    STANDARD,
    /** 15% off, but nothing comes back on cancellation. */
    NON_REFUNDABLE
}
package hotel.reservations;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Keeps the reservations in memory: everything is lost when the service restarts. */
public final class ReservationStore {

    private final Map<Long, Reservation> reservationsById = new LinkedHashMap<>();
    private long lastId = 0;

    synchronized long nextId() {
        lastId++;
        return lastId;
    }

    synchronized void save(Reservation reservation) {
        reservationsById.put(reservation.id(), reservation);
    }

    public synchronized Optional<Reservation> find(long id) {
        return Optional.ofNullable(reservationsById.get(id));
    }

    public synchronized List<Reservation> all() {
        return new ArrayList<>(reservationsById.values());
    }
}
package hotel.reports;

import static org.junit.jupiter.api.Assertions.assertEquals;

import hotel.messages.EmailSender;
import hotel.messages.SentMessages;
import hotel.reservations.Guest;
import hotel.reservations.NewReservation;
import hotel.reservations.PriceCalculator;
import hotel.reservations.RatePlan;
import hotel.reservations.Reservation;
import hotel.reservations.ReservationService;
import hotel.reservations.ReservationStore;
import hotel.rooms.Rooms;
import java.time.LocalDate;
import java.time.YearMonth;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class ReportsTest {

    private final Rooms rooms = new Rooms();
    private final ReservationStore store = new ReservationStore();
    private final ReservationService service =
            new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(new SentMessages()));

    private Reservation book(int roomNumber, String checkIn, String checkOut, RatePlan plan) {
        Guest guest = new Guest("Bruno Lima", "bruno@example.com", "987.654.321-00");
        return service.create(new NewReservation(
                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), 1, plan));
    }

    @BeforeEach
    void someReservations() {
        Reservation april = book(201, "2027-04-01", "2027-04-03", RatePlan.STANDARD);
        Reservation lateMarch = book(101, "2027-03-30", "2027-04-02", RatePlan.NON_REFUNDABLE);
        Reservation suite = book(301, "2027-04-02", "2027-04-04", RatePlan.STANDARD);
        book(102, "2027-04-01", "2027-04-05", RatePlan.STANDARD); // never paid
        Reservation cancelled = book(202, "2027-04-01", "2027-04-02", RatePlan.STANDARD);
        service.confirm(april.id());
        service.confirm(lateMarch.id());
        service.confirm(suite.id());
        service.checkIn(suite.id());
        service.confirm(cancelled.id());
        service.cancel(cancelled.id());
    }

    @Test
    void occupancyListsThePaidReservationsCoveringTheNight() {
        String csv = new OccupancyReport(rooms, store).generate(LocalDate.of(2027, 4, 1));

        assertEquals("""
                room,type,reservation,check_in,check_out
                101,STANDARD,2,2027-03-30,2027-04-02
                201,DELUXE,1,2027-04-01,2027-04-03
                total,2/5
                """, csv);
    }

    @Test
    void theCheckOutNightIsNotOccupied() {
        String csv = new OccupancyReport(rooms, store).generate(LocalDate.of(2027, 4, 3));

        assertEquals("""
                room,type,reservation,check_in,check_out
                301,SUITE,3,2027-04-02,2027-04-04
                total,1/5
                """, csv);
    }

    @Test
    void revenueSumsTheMoneyKeptFromReservationsStartingInTheMonth() {
        String csv = new RevenueReport(store).generate(YearMonth.of(2027, 4));

        // the unpaid reservation and the refunded cancellation bring nothing
        assertEquals("""
                reservation,room,check_in,check_out,status,amount
                1,201,2027-04-01,2027-04-03,CONFIRMED,779.80
                3,301,2027-04-02,2027-04-04,CHECKED_IN,1159.80
                total,1939.60
                """, csv);
    }

    @Test
    void aCancelledNonRefundableReservationStillCountsAsRevenue() {
        Reservation may = book(101, "2027-05-10", "2027-05-11", RatePlan.NON_REFUNDABLE);
        service.confirm(may.id());
        service.cancel(may.id());

        String csv = new RevenueReport(store).generate(YearMonth.of(2027, 5));

        assertEquals("""
                reservation,room,check_in,check_out,status,amount
                6,101,2027-05-10,2027-05-11,CANCELLED,212.42
                total,212.42
                """, csv);
    }

    @Test
    void anEmptyMonthHasOnlyTheTotal() {
        String csv = new RevenueReport(store).generate(YearMonth.of(2027, 6));

        assertEquals("""
                reservation,room,check_in,check_out,status,amount
                total,0.00
                """, csv);
    }
}
package hotel.reservations;

import hotel.documents.ReservationReceipt;
import hotel.messages.EmailSender;
import hotel.rooms.Room;
import hotel.rooms.Rooms;
import java.math.BigDecimal;

/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
public final class ReservationService {

    static final String HOTEL_NAME = "Pousada Maré Alta";

    private final Rooms rooms;
    private final ReservationStore store;
    private final PriceCalculator priceCalculator;
    private final EmailSender emailSender;

    public ReservationService(
            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
        this.rooms = rooms;
        this.store = store;
        this.priceCalculator = priceCalculator;
        this.emailSender = emailSender;
    }

    public synchronized Reservation create(NewReservation request) {
        if (!request.checkOut().isAfter(request.checkIn())) {
            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
        }
        if (request.guests() < 1) {
            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
        }
        Room room = rooms.find(request.roomNumber())
                .orElseThrow(() -> new HotelException(
                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
        if (request.guests() > room.capacity()) {
            throw new HotelException(
                    ErrorCode.CAPACITY_EXCEEDED,
                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
        }
        boolean roomTaken = store.all().stream()
                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
        if (roomTaken) {
            throw new HotelException(
                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
        }
        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
        Reservation reservation = new Reservation(store.nextId(), request, price);
        store.save(reservation);
        return reservation;
    }

    public Reservation find(long reservationId) {
        return store.find(reservationId)
                .orElseThrow(() -> new HotelException(
                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    }

